547: // IsConversationIdle checks if a conversation has been idle for the required duration (SPEC §6.2: 15 minutes).
548: // Killed sessions are considered immediately idle.
549: func IsConversationIdle(summary ConversationSummary, transcriptPath string, now time.Time, idleCutoff time.Duration) bool {
550: 	if idleCutoff <= 0 {
551: 		idleCutoff = 15 * time.Minute
552: 	}
553: 	if now.IsZero() {
554: 		now = time.Now()
555: 	}
556: 
557: 	if summary.Killed {
558: 		return true
559: 	}
560: 
561: 	if !summary.LastModifiedTime.IsZero() {
562: 		if now.Sub(summary.LastModifiedTime) < idleCutoff {
563: 			return false
564: 		}
565: 	}
566: 
567: 	if summary.NotFullyIdle {
568: 		return false
569: 	}
570: 
571: 	if transcriptPath != "" {
572: 		if fi, err := os.Stat(transcriptPath); err == nil {
573: 			if now.Sub(fi.ModTime()) < idleCutoff {
574: 				return false
575: 			}
576: 		}
577: 	}
578: 
579: 	return true
580: }
