package antigravity

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/dossiers"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/index"
)

func TestPreToolUse_AllowByDefault(t *testing.T) {
	ctx := context.Background()

	tests := []struct {
		name    string
		payload string
	}{
		{name: "empty bytes", payload: ""},
		{name: "empty json object", payload: "{}"},
		{name: "invalid json", payload: "not-json"},
		{name: "empty tool name", payload: `{"toolName": "", "workspacePaths": ["/tmp"]}`},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			out, err := HandlePreToolUse(ctx, []byte(tt.payload))
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if string(out) != string(allowResponse) {
				t.Errorf("got %q, want %q", string(out), string(allowResponse))
			}
		})
	}
}

func TestPreToolUse_FastExits(t *testing.T) {
	ctx := context.Background()

	tests := []struct {
		name    string
		payload string
		env     map[string]string
	}{
		{
			name:    "REPO_MEMORY_DISABLED",
			payload: `{"toolName": "replace_file_content", "toolCall": {"name": "replace_file_content", "args": {"TargetFile": "main.go"}}}`,
			env:     map[string]string{"REPO_MEMORY_DISABLED": "1"},
		},
		{
			name:    "REPO_MEMORY_HOUSEKEEPING",
