func TestPreToolUse_EditWithGate(t *testing.T) {
	ctx := context.Background()
	workspace, idxPath := setupEnrolledWorkspace(t)

	targetFile := filepath.Join(workspace, "auth_provider.go")
	if err := os.WriteFile(targetFile, []byte("package auth\n"), 0644); err != nil {
		t.Fatal(err)
	}

	idx, err := index.NewIndex(idxPath)
	if err != nil {
		t.Fatal(err)
	}

	gateEntry := dossiers.Entry{
		ID:           "sec-gate-001",
		Type:         dossiers.EntryTypeInvariant,
		DossierScope: "auth",
		Text:         "Security sensitive authentication logic: gate: edit requires user approval",
		Anchors:      []string{"auth_provider.go"},
	}
	if err := idx.UpsertEntry(ctx, gateEntry); err != nil {
		t.Fatal(err)
	}
	if err := idx.UpsertEntryAnchors(ctx, gateEntry.ID, gateEntry.Anchors); err != nil {
		t.Fatal(err)
	}
	idx.Close()

	// 1. Tool call with absolute TargetFile path
	payload := `{
		"conversationId": "conv-gate-test",
		"toolName": "replace_file_content",
		"toolCall": {
			"name": "replace_file_content",
			"args": {"TargetFile": "` + targetFile + `"}
		},
		"workspacePaths": ["` + workspace + `"]
	}`

	out, err := HandlePreToolUse(ctx, []byte(payload))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	var resp PreToolUseResponse
	if err := json.Unmarshal(out, &resp); err != nil {
		t.Fatalf("failed to unmarshal PreToolUseResponse: %v, raw: %s", err, string(out))
	}

	if resp.Decision != "force_ask" {
		t.Errorf("expected decision force_ask, got %q", resp.Decision)
	}
	if !strings.Contains(resp.Reason, "[REPO-MEMORY sec-gate-001]") {
		t.Errorf("expected [REPO-MEMORY sec-gate-001] tag in reason, got %q", resp.Reason)
	}
	if !strings.Contains(resp.Reason, "gate: edit") {
		t.Errorf("expected 'gate: edit' text in reason, got %q", resp.Reason)
	}

	// 2. Tool call with relative TargetFile path
	payloadRel := `{
		"conversationId": "conv-gate-test",
		"toolName": "write_to_file",
		"toolCall": {
			"name": "write_to_file",
			"args": {"TargetFile": "auth_provider.go"}
		},
		"workspacePaths": ["` + workspace + `"]
	}`

	outRel, err := HandlePreToolUse(ctx, []byte(payloadRel))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	var respRel PreToolUseResponse
	if err := json.Unmarshal(outRel, &respRel); err != nil {
		t.Fatalf("failed to unmarshal PreToolUseResponse: %v, raw: %s", err, string(outRel))
	}

	if respRel.Decision != "force_ask" {
		t.Errorf("expected decision force_ask, got %q", respRel.Decision)
	}
	if !strings.Contains(respRel.Reason, "[REPO-MEMORY sec-gate-001]") {
		t.Errorf("expected [REPO-MEMORY sec-gate-001] tag in reason, got %q", respRel.Reason)
	}
}

